import{channelEntries}from"#compiled/@eve/catalog/index.js";const CHANNEL_SCAFFOLDS=[{slug:`eve`,kind:`web`,registryItem:`channel/web`,label:`Web Chat`,hint:`Next.js app`},{slug:`slack`,kind:`slack`,registryItem:`channel/slack`,label:`Slack`,hint:`Slack app mentions and DMs`}];function buildScaffoldableChannels(){let e=new Set(channelEntries().filter(e=>e.surfaces.scaffoldable).map(e=>e.slug)),t=[];for(let n of CHANNEL_SCAFFOLDS){if(!e.delete(n.slug))throw Error(`Channel overlay "${n.slug}" is not a scaffoldable channel in @eve/catalog.`);let r={slug:n.slug,kind:n.kind,registryItem:n.registryItem,label:n.label};n.hint!==void 0&&(r.hint=n.hint),t.push(r)}if(e.size>0){let t=[...e].sort().join(`, `);throw Error(`Scaffoldable catalog channels missing a scaffolder overlay: ${t}.`)}return t}const SCAFFOLDABLE_CHANNELS=buildScaffoldableChannels();export{SCAFFOLDABLE_CHANNELS};